"""Tests for :mod:`holodeck.librarian.flows_lib`.

The load-bearing tests here are the ones that do not involve random numbers:

* :func:`test_loudest_per_bin_selection` pins the "which cell holds the l-th loudest binary"
  search against a brute-force reference, with the Poisson counts injected rather than drawn.
* :func:`test_rank_cws_matches_reference` pins the across-band ranking against a brute-force
  reference.

Everything downstream of those is deterministic, so if they hold, a library's contents are pinned.


** These tests are generated by Claude **

"""

import numpy as np
import pytest

import holodeck as holo
from holodeck import utils
from holodeck.constants import MSOL, MPC, YR
from holodeck.librarian import flows_lib


class _FakeRNG:
    """Stands in for a ``numpy.random.Generator``, returning pre-set counts instead of drawing.

    ``loudest_per_bin`` calls ``rng.poisson(lam, size=(R, B))`` once per frequency bin, in
    increasing bin order, so the counts are handed back in that order.
    """

    def __init__(self, counts_per_freq):
        self._counts = list(counts_per_freq)
        self._ii = 0

    def poisson(self, lam, size=None):
        out = np.asarray(self._counts[self._ii])
        self._ii += 1
        assert out.shape == size, f"injected counts {out.shape} != requested {size}"
        return out


def _brute_force_loudest(counts, h2, cell, nloudest):
    """Reference implementation: expand the counts into individual binaries and take the first N.

    ``counts``, ``h2``, and ``cell`` are all ordered loudest-first.
    """
    hc2 = np.repeat(h2, counts)[:nloudest]
    idx = np.repeat(cell, counts)[:nloudest]
    return hc2, idx


