def test_cw_columns_values_and_layout():
    """Columns must match the closed-form values, and land in (1, nrank, nreal)."""
    from holodeck import cosmo

    R, K = 3, 2
    M, Q, Z, F = 2, 2, 2, 3

    mt = np.array([1e8, 1e9]) * MSOL
    mr = np.array([0.3, 0.9])
    redz = np.full((M, Q, Z, F), 0.5)
    fobs = np.array([1e-9, 2e-9, 3e-9])

    # one source per (realization, rank), all live except the last, which is a dead slot
    bidx = np.arange(R * K).reshape(R, K) % (M * Q * Z)
    fidx = np.arange(R * K).reshape(R, K) % F
    lidx = np.zeros((R, K), dtype=int)
    hc = np.full((R, K), 1e-16)
    fidx[-1, -1] = -1

    ranked = dict(hc=hc, bidx=bidx, fidx=fidx, lidx=lidx)
    out = flows_lib.cw_columns(ranked, mt, mr, redz, fobs)

    for key in flows_lib.CW_KEYS + flows_lib.PROV_KEYS + flows_lib.IDX_KEYS:
        assert out[key].shape == (1, K, R), f"{key} has shape {out[key].shape}"

    mm, qq, _zz = np.unravel_index(bidx, (M, Q, Z))
    mtot, mrat = mt[mm], mr[qq]
    mchirp = mtot * mrat**(3/5) / (1 + mrat)**(6/5)
    want_mc = np.log10(mchirp * 1.5 / MSOL)
    want_dc = np.log10(np.asarray(cosmo.z_to_dcom(np.full((R, K), 0.5))) / MPC)
    want_fo = np.log10(fobs[np.where(fidx >= 0, fidx, 0)])

    live = fidx >= 0
    assert np.allclose(out['log10_mc'][0].T[live], want_mc[live])
    assert np.allclose(out['log10_dc'][0].T[live], want_dc[live])
    assert np.allclose(out['log10_fo'][0].T[live], want_fo[live])

    # the dead slot is NaN in every float column, and -1 in the index columns
    for key in flows_lib.CW_KEYS + flows_lib.PROV_KEYS:
        assert np.isnan(out[key][0, -1, -1]), f"{key} dead slot is not NaN"
    for key in flows_lib.IDX_KEYS:
        assert out[key][0, -1, -1] == -1, f"{key} dead slot is not -1"


def test_cw_columns_stalled_redshift_is_nan():
    """holodeck's -1 redshift sentinel must become NaN, never a negative distance."""
    R, K = 1, 2
    M, Q, Z, F = 2, 2, 2, 1
    mt = np.array([1e8, 1e9]) * MSOL
    mr = np.array([0.3, 0.9])
    redz = np.full((M, Q, Z, F), 0.5)
    redz[0, 0, 0, 0] = -1.0        # stalled
    fobs = np.array([1e-9])

    ranked = dict(
        hc=np.full((R, K), 1e-16),
        bidx=np.array([[0, 1]]),   # first source sits in the stalled cell
        fidx=np.zeros((R, K), dtype=int),
        lidx=np.zeros((R, K), dtype=int),
    )
    out = flows_lib.cw_columns(ranked, mt, mr, redz, fobs)
    assert np.isnan(out['log10_dc'][0, 0, 0]), "stalled bin did not become NaN"
    assert np.isfinite(out['log10_dc'][0, 1, 0]), "live bin was masked out"


